#include <vector>
#include <algorithm>

class Solution {
public:
    long long largestPerimeter(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        long long prefix = 0;
        long long ans = -1;
        for (int num : nums) {
            if (num < prefix) {
                ans = prefix + num;
            }
            prefix += num;
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public long largestPerimeter(int[] nums) {
        Arrays.sort(nums);
        long prefix = 0;
        long ans = -1;
        for (int num : nums) {
            if (num < prefix) {
                ans = prefix + num;
            }
            prefix += num;
        }
        return ans;
    }
}

var largestPerimeter = function(nums) {
    nums.sort((a, b) => a - b);
    let prefix = 0;
    let ans = -1;
    for (const num of nums) {
        if (num < prefix) {
            ans = prefix + num;
        }
        prefix += num;
    }
    return ans;
};
